import React, { useState, useEffect } from 'react';
import { documentService } from '../../services/documentService';
import { clientService } from '../../services/clientService';
import { useAuth } from '../../contexts/AuthContext';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import {
  FileText,
  Search,
  Download,
  Trash2,
  Eye,
  ChevronRight,
  Loader,
  AlertCircle,
  Filter,
  X,
} from 'lucide-react';
import Swal from 'sweetalert2';

export const AdminDocumentsManager = () => {
  const { user } = useAuth();
  const [clients, setClients] = useState([]);
  const [selectedClient, setSelectedClient] = useState(null);
  const [documents, setDocuments] = useState([]);
  const [filteredDocuments, setFilteredDocuments] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedType, setSelectedType] = useState('all');
  const [publicOnly, setPublicOnly] = useState(false);
  const [loading, setLoading] = useState(false);
  const [clientsLoading, setClientsLoading] = useState(true);
  const [expandedClient, setExpandedClient] = useState(null);

  const years = Array.from({ length: 5 }, (_, i) => 
    new Date().getFullYear() - i
  );

  const documentTypes = [
    { value: 'all', label: 'Todos los tipos' },
    { value: 'report', label: '📊 Reportes' },
    { value: 'certification', label: '✓ Certificaciones' },
    { value: 'manual', label: '📖 Manuales' },
    { value: 'permit', label: '📜 Permisos' },
  ];

  // Cargar clientes
  useEffect(() => {
    loadClients();
  }, []);

  // Cargar documentos cuando cambia el cliente o filtros
  useEffect(() => {
    if (selectedClient) {
      loadClientDocuments();
    }
  }, [selectedClient, selectedYear, selectedType, publicOnly]);

  // Aplicar búsqueda
  useEffect(() => {
    if (!selectedClient) return;

    const timer = setTimeout(() => {
      let filtered = documents;

      if (searchTerm.trim()) {
        filtered = filtered.filter(doc =>
          doc.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          doc.description.toLowerCase().includes(searchTerm.toLowerCase())
        );
      }

      setFilteredDocuments(filtered);
    }, 300);

    return () => clearTimeout(timer);
  }, [searchTerm, documents]);

  const loadClients = async () => {
    try {
      setClientsLoading(true);
      const data = await clientService.getAll();
      setClients(data);
      if (data.length > 0) {
        setSelectedClient(data[0]._id);
      }
    } catch (error) {
      console.error('Error loading clients:', error);
      Swal.fire('Error', 'Error al cargar clientes', 'error');
    } finally {
      setClientsLoading(false);
    }
  };

  const loadClientDocuments = async () => {
    if (!selectedClient) return;

    try {
      setLoading(true);
      const params = {
        year: selectedYear.toString(),
      };

      if (selectedType !== 'all') {
        params.document_type = selectedType;
      }

      if (publicOnly) {
        params.is_public = 'true';
      }

      const data = await documentService.getClientAllDocuments(selectedClient, params);
      setDocuments(data);
      setFilteredDocuments(data);
    } catch (error) {
      console.error('Error loading documents:', error);
      Swal.fire('Error', 'Error al cargar documentos', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async (document) => {
    try {
      const blob = await documentService.download(document._id);
      const url = window.URL.createObjectURL(blob);
      const a = window.document.createElement('a');
      a.href = url;
      a.download = document.file_name;
      window.document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      window.document.body.removeChild(a);
    } catch (error) {
      Swal.fire('Error', 'No se pudo descargar el documento', 'error');
    }
  };

  const handleDelete = async (document) => {
    const result = await Swal.fire({
      title: '¿Eliminar documento?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      confirmButtonText: 'Sí, eliminar',
      cancelButtonText: 'Cancelar',
    });

    if (result.isConfirmed) {
      try {
        await documentService.delete(document._id);
        Swal.fire({
          icon: 'success',
          title: 'Eliminado',
          text: 'Documento eliminado exitosamente',
          timer: 2000,
          showConfirmButton: false,
        });
        loadClientDocuments();
      } catch (error) {
        Swal.fire('Error', 'Error al eliminar el documento', 'error');
      }
    }
  };

  const getDocumentTypeIcon = (type) => {
    const icons = {
      report: '📊',
      certification: '✓',
      manual: '📖',
      permit: '📜',
    };
    return icons[type] || '📄';
  };

  const getSelectedClientName = () => {
    const client = clients.find(c => c._id === selectedClient);
    return client?.company_name || 'Selecciona un cliente';
  };

  if (clientsLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader className="w-12 h-12 animate-spin text-green-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900">
          📁 Gestión de Documentos por Cliente
        </h2>
        <p className="text-gray-600 mt-1">
          Visualiza y gestiona los documentos de cada cliente
        </p>
      </div>

      {/* Selector de Cliente */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Cliente Seleccionado</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <select
              value={selectedClient || ''}
              onChange={(e) => {
                setSelectedClient(e.target.value);
                setExpandedClient(null);
              }}
              className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent font-semibold text-lg"
            >
              {clients.map(client => (
                <option key={client._id} value={client._id}>
                  {client.company_name} • {client.contact_person}
                </option>
              ))}
            </select>

            {selectedClient && (
              <div className="grid grid-cols-2 gap-3 p-4 bg-green-50 rounded-lg">
                <div>
                  <p className="text-xs text-gray-600 uppercase">Contacto</p>
                  <p className="font-semibold text-gray-900">{clients.find(c => c._id === selectedClient)?.contact_person}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-600 uppercase">Teléfono</p>
                  <p className="font-semibold text-gray-900">{clients.find(c => c._id === selectedClient)?.phone}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-600 uppercase">Email</p>
                  <p className="font-semibold text-gray-900 text-sm">{clients.find(c => c._id === selectedClient)?.email}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-600 uppercase">Industria</p>
                  <p className="font-semibold text-gray-900">{clients.find(c => c._id === selectedClient)?.industry}</p>
                </div>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Filtros */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Filter className="w-5 h-5" />
            Filtros
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Búsqueda
              </label>
              <div className="relative">
                <Search className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
                <Input
                  placeholder="Buscar..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>

            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Año
              </label>
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-green-500"
              >
                {years.map(year => (
                  <option key={year} value={year}>{year}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Tipo
              </label>
              <select
                value={selectedType}
                onChange={(e) => setSelectedType(e.target.value)}
                className="w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-green-500"
              >
                {documentTypes.map(type => (
                  <option key={type.value} value={type.value}>
                    {type.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="text-sm font-semibold text-gray-700 block mb-2">
                Visibilidad
              </label>
              <button
                onClick={() => setPublicOnly(!publicOnly)}
                className={`w-full px-3 py-2 rounded-lg font-semibold transition-all ${
                  publicOnly
                    ? 'bg-green-600 text-white'
                    : 'bg-gray-100 text-gray-900 hover:bg-gray-200'
                }`}
              >
                {publicOnly ? '🌍 Solo Públicos' : '👁️ Todos'}
              </button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Documentos */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader className="w-12 h-12 animate-spin text-green-600" />
        </div>
      ) : filteredDocuments.length === 0 ? (
        <Card className="bg-gray-50 text-center py-12">
          <FileText className="w-16 h-16 mx-auto text-gray-300 mb-4" />
          <p className="text-gray-600">
            {searchTerm ? 'No hay documentos que coincidan' : 'No hay documentos para este cliente'}
          </p>
        </Card>
      ) : (
        <div className="space-y-3">
          {filteredDocuments.map((doc) => (
            <Card key={doc._id} className="hover:shadow-lg transition-shadow">
              <CardContent className="p-4 sm:p-6">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start gap-3">
                      <span className="text-2xl flex-shrink-0">
                        {getDocumentTypeIcon(doc.document_type)}
                      </span>
                      <div className="flex-1 min-w-0">
                        <h3 className="font-bold text-gray-900 truncate text-lg mb-1">
                          {doc.title}
                        </h3>
                        {doc.description && (
                          <p className="text-sm text-gray-600 line-clamp-2 mb-2">
                            {doc.description}
                          </p>
                        )}
                        <div className="flex flex-wrap items-center gap-2 text-xs">
                          {doc.is_public && (
                            <Badge className="bg-blue-100 text-blue-800">
                              🌍 Público
                            </Badge>
                          )}
                          <Badge variant="outline">
                            {doc.document_type}
                          </Badge>
                          <span className="text-gray-500">
                            {new Date(doc.created_at).toLocaleDateString('es-ES')}
                          </span>
                          <span className="text-gray-500">
                            {(doc.file_size / 1024 / 1024).toFixed(2)} MB
                          </span>
                          <span className="text-gray-500">
                            Por: {doc.uploaded_by.full_name}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-2 flex-shrink-0 ml-2">
                    <Button
                      onClick={() => handleDownload(doc)}
                      size="sm"
                      className="bg-green-600 hover:bg-green-700"
                      title="Descargar"
                    >
                      <Download className="w-4 h-4" />
                    </Button>
                    <Button
                      onClick={() => handleDelete(doc)}
                      size="sm"
                      className="bg-red-600 hover:bg-red-700"
                      title="Eliminar"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}

          {/* Resumen */}
          <Card className="bg-blue-50 border-blue-200">
            <CardContent className="p-4 text-sm text-blue-800">
              <p className="font-semibold">
                Documentos mostrados: {filteredDocuments.length} de {documents.length}
              </p>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
};

export default AdminDocumentsManager;
